using var root = new LabScriptedAdapter();
LabAdapterPort alias = root;
using var a = new LabController(root);
using var b = new LabController(root);
Console.WriteLine(ReferenceEquals(alias, root)); // True
a.Dispose();
Console.WriteLine(root.Disposed); // False
Console.WriteLine(root.HandlerCount); // 1
string id = b.Submit("QueryState", 0);
root.Emit(new LabCompletion(id, b.Session, "Completed"));
Console.WriteLine(b.Results[id]); // Completed

using var first = new LabScriptedAdapter();
using var second = new LabScriptedAdapter();
LabAdapterPort current = first;
using var old = new LabController(current);
current = second; // old仍保存first
string oldId = old.Submit("QueryState", 0);
Console.WriteLine(first.Sent.Count); // 1
Console.WriteLine(second.Sent.Count); // 0
old.Dispose();
using var fresh = new LabController(current);
string id = fresh.Submit("QueryState", 0);
second.Emit(new LabCompletion(id, fresh.Session, "Completed"));
Console.WriteLine(fresh.Results[id]); // Completed
